INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass MRP immer manuell durchgeführt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Meist softwaregestützt"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich MRP für eine IT-Firma einrichte?', 3, '[{"text": "Datenqualität", "correct": true, "because": "Sichert Planung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu MRP in der IT?', 5, '[{"text": "Materialstammdaten", "correct": true, "because": "Basis der Planung"}, {"text": "Bedarfsprognosen", "correct": true, "because": "Bestimmen Menge"}, {"text": "Büromöbel", "correct": false, "because": "Kein Faktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MRP plant Materialbedarf. b) Es ist immer ungenau.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann präzise sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich MRP in einer IT-Firma einsetze?', 4, '[{"text": "Bestandsdaten", "correct": false, "because": "Wichtige Grundlage"}, {"text": "Produktionspläne", "correct": false, "because": "Bestimmen Bedarf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MRP nur für große Firmen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für KMU nützlich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit MRP in einem IT-System?', 3, '[{"text": "Materialverfügbarkeit", "correct": true, "because": "Sichert Produktion"}, {"text": "Schnellste Planung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei MRP entscheidend?', 5, '[{"text": "Bestandsmanagement", "correct": true, "because": "Verfolgt Lager"}, {"text": "Bedarfsplanung", "correct": true, "because": "Bestimmt Menge"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) MRP reduziert Überbestände. b) Es ist immer manuell. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Softwaregestützt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um MRP in einer IT-Firma einzusetzen?', 4, '[{"text": "Materialdaten", "correct": false, "because": "Basis der Planung"}, {"text": "Zeitpläne", "correct": false, "because": "Koordinieren Bedarf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist MRP immer ungenau?', 2, '[{"text": "Nein", "correct": true, "because": "Kann präzise sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet MRP in der IT?', 4, '[{"text": "Kostensenkung", "correct": true, "because": "Vermeidet Überbestände"}, {"text": "Effiziente Planung", "correct": true, "because": "Optimiert Produktion"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass MRP nur für Produktionsfirmen relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IT-Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um MRP effektiv in einer IT-Firma einzusetzen?', 3, '[{"text": "Genaue Daten", "correct": true, "because": "Sichern Planung"}, {"text": "Schnellste Software", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MRP kann Lieferzeiten optimieren. b) Es ist immer ungenau.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann präzise sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei MRP?', 5, '[{"text": "Produktionspläne", "correct": true, "because": "Bestimmen Bedarf"}, {"text": "Lagerbestände", "correct": true, "because": "Verhindern Überbestände"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich MRP in einer IT-Firma einsetze?', 3, '[{"text": "Bestandsdaten", "correct": false, "because": "Wichtige Grundlage"}, {"text": "Bedarfsprognosen", "correct": false, "because": "Bestimmen Menge"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist MRP immer für große Firmen geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für KMU"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob MRP nur für physische Materialien gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch digitale Ressourcen"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für MRP?', 4, '[{"text": "Genaue Datenbasis", "correct": true, "because": "Sichert Planung"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
